module Top;
    int i_header = 12, i_len = 5, i_crc = 42;
    byte i_data[];
    int o_header, o_len, o_crc;
    byte o_data[];
    byte pkt[$];
    initial begin
        i_data = new[5];
        foreach (i_data[k]) i_data[k] = byte'(k + 1);
        pkt = {<< 8 {i_header, i_len, i_data with [1 +: 3], i_crc}};
        $display("pkt size=%0d pkt[4]=%0d pkt[6]=%0d", pkt.size(), pkt[4], pkt[6]);
        {<< 8 {o_header, o_len, o_data with [0 +: o_len], o_crc}} = {<< 8 {i_header, i_len, i_data, i_crc}};
        $display("len=%0d crc=%0d size=%0d data[0]=%0d data[4]=%0d", o_len, o_crc, o_data.size(), o_data[0], o_data[4]);
    end
endmodule
